40	    fn resolve_scoped_path(
41	        &self,
42	        relative_path: Option<&str>,
43	    ) -> Result<PathBuf, MemoriesBackendError> {
44	        let Some(relative_path) = relative_path else {
45	            return Ok(self.root.clone());
46	        };
47	        let relative = Path::new(relative_path);
48	        if relative.components().any(|component| {
49	            matches!(
50	                component,
51	                Component::ParentDir | Component::RootDir | Component::Prefix(_)
52	            )
53	        }) {
54	            return Err(MemoriesBackendError::invalid_path(
55	                relative_path,
56	                "must stay within the memories root",
57	            ));
58	        }
59	        Ok(self.root.join(relative))
60	    }
