62	    async fn metadata_or_none(
63	        path: &Path,
64	    ) -> Result<Option<std::fs::Metadata>, MemoriesBackendError> {
65	        match tokio::fs::symlink_metadata(path).await {
66	            Ok(metadata) => Ok(Some(metadata)),
67	            Err(err) if err.kind() == std::io::ErrorKind::NotFound => Ok(None),
68	            Err(err) => Err(err.into()),
69	        }
70	    }
