73	impl MemoriesBackend for LocalMemoriesBackend {
74	    async fn list(
75	        &self,
76	        request: ListMemoriesRequest,
77	    ) -> Result<ListMemoriesResponse, MemoriesBackendError> {
78	        let max_results = request.max_results.min(MAX_LIST_RESULTS);
79	        let start = self.resolve_scoped_path(request.path.as_deref())?;
80	        let mut entries = Vec::new();
81	        let truncated = collect_entries(&self.root, &start, &mut entries, max_results).await?;
82	        entries.sort_by(|left, right| left.path.cmp(&right.path));
83	        Ok(ListMemoriesResponse {
84	            path: request.path,
85	            entries,
86	            truncated,
87	        })
88	    }
89	
90	    async fn read(
91	        &self,
92	        request: ReadMemoryRequest,
93	    ) -> Result<ReadMemoryResponse, MemoriesBackendError> {
94	        let path = self.resolve_scoped_path(Some(request.path.as_str()))?;
95	        let Some(metadata) = Self::metadata_or_none(&path).await? else {
96	            return Err(MemoriesBackendError::NotFile { path: request.path });
97	        };
98	        reject_symlink(&request.path, &metadata)?;
99	        if !metadata.is_file() {
100	            return Err(MemoriesBackendError::NotFile { path: request.path });
101	        }
102	
103	        let original_content = tokio::fs::read_to_string(&path).await?;
104	        let max_tokens = if request.max_tokens == 0 {
105	            DEFAULT_READ_MAX_TOKENS
106	        } else {
107	            request.max_tokens
108	        };
109	        let content = truncate_text(&original_content, TruncationPolicy::Tokens(max_tokens));
110	        let truncated = content != original_content;
111	        Ok(ReadMemoryResponse {
112	            path: request.path,
113	            content,
114	            truncated,
115	        })
116	    }
117	
118	    async fn search(
119	        &self,
120	        request: SearchMemoriesRequest,
121	    ) -> Result<SearchMemoriesResponse, MemoriesBackendError> {
122	        let query = request.query.trim();
123	        if query.is_empty() {
124	            return Err(MemoriesBackendError::EmptyQuery);
125	        }
126	
127	        let max_results = request.max_results.min(MAX_SEARCH_RESULTS);
128	        let start = self.resolve_scoped_path(request.path.as_deref())?;
129	        let mut matches = Vec::new();
130	        let truncated =
131	            search_entries(&self.root, &start, query, &mut matches, max_results).await?;
132	        matches.sort_by(|left, right| {
133	            left.path
134	                .cmp(&right.path)
135	                .then(left.line_number.cmp(&right.line_number))
136	        });
137	        Ok(SearchMemoriesResponse {
138	            query: request.query,
139	            path: request.path,
140	            matches,
141	            truncated,
142	        })
143	    }
144	}
