149	    entries: &mut Vec<MemoryEntry>,
150	    max_results: usize,
151	) -> Result<bool, MemoriesBackendError> {
152	    if max_results == 0 {
153	        return Ok(false);
154	    }
155	    let Some(metadata) = LocalMemoriesBackend::metadata_or_none(current).await? else {
156	        return Ok(false);
157	    };
158	    reject_symlink(&display_relative_path(root, current), &metadata)?;
159	    if metadata.is_file() {
160	        entries.push(MemoryEntry {
