172	        for path in read_sorted_dir_paths(&dir_path).await? {
173	            if entries.len() >= max_results {
174	                return Ok(true);
175	            }
176	            let Some(metadata) = LocalMemoriesBackend::metadata_or_none(&path).await? else {
177	                continue;
178	            };
179	            if metadata.file_type().is_symlink() {
180	                continue;
181	            }
182	
183	            let relative = display_relative_path(root, &path);
